INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6955730, 1048488, 108580, '<td valign="top">Just a hint of it. Very special image.</td>', 'Just a hint of it. Very special image.', '2013-01-12 14:59:40.000000', NULL, 1),
(6955731, 1048559, 108580, '<td valign="top">Start with making eye contact, one at a time is good :)<br/>ETA: Typo<br/><br/><i>Message edited by author 2013-01-16 01:53:33.</i></td>', 'Start with making eye contact, one at a time is good :)ETA: Typo', '2013-01-12 15:00:13.000000', '2013-01-16 01:53:33.000000', 1),
(6955733, 1047989, 108580, '<td valign="top">Barbie paradise. Great IR.</td>', 'Barbie paradise. Great IR.', '2013-01-12 15:01:08.000000', NULL, 1),
(6955734, 1047994, 108580, '<td valign="top">Nice lines, complimentary BG. Drum, or  Old Holbourne and Ritmeesters... :(<br/>Quit. I''m on week 55 and the morning phlegm is only now starting to slow down.</td>', 'Nice lines, complimentary BG. Drum, or  Old Holbourne and Ritmeesters... :(Quit. I''m on week 55 and the morning phlegm is only now starting to slow down.', '2013-01-12 15:03:10.000000', NULL, 1),
(6955757, 1047733, 30049, '<td valign="top">Seems somewhat flat (low contrast) and washed out.</td>', 'Seems somewhat flat (low contrast) and washed out.', '2013-01-12 15:59:21.000000', NULL, 1),
(6955759, 1048496, 30049, '<td valign="top">Like the scene and the concept - wish the light was more dynamic.</td>', 'Like the scene and the concept - wish the light was more dynamic.', '2013-01-12 16:00:12.000000', NULL, 1),
(6955760, 1048172, 30049, '<td valign="top">They haven''t bulldozed this place yet?!</td>', 'They haven''t bulldozed this place yet?!', '2013-01-12 16:00:34.000000', NULL, 1),
(6955762, 1048498, 30049, '<td valign="top">Lose the shoes!  You''ll easily drop a pound or two.  :-)</td>', 'Lose the shoes!  You''ll easily drop a pound or two.  :-)', '2013-01-12 16:02:06.000000', NULL, 1),
(6955767, 1048063, 30049, '<td valign="top">:-)  Your resolution should be to use the selection tool better in post-processing!</td>', ':-)  Your resolution should be to use the selection tool better in post-processing!', '2013-01-12 16:08:03.000000', NULL, 1),
(6955769, 1048485, 30049, '<td valign="top">Clever!  Wonderful capture of this sky color.</td>', 'Clever!  Wonderful capture of this sky color.', '2013-01-12 16:09:20.000000', NULL, 1),
(6956122, 1048564, 108580, '<td valign="top">These socks belong to <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=126903" rel="nofollow" target="_blank">thrumyiis</a>! DMC and thoughtful challenge entry. Needs a bit more oomf.</td>', 'These socks belong to  thrumyiis! DMC and thoughtful challenge entry. Needs a bit more oomf.', '2013-01-13 01:20:03.000000', NULL, 1),
(6956125, 1048495, 63812, '<td valign="top">very nice!</td>', 'very nice!', '2013-01-13 01:48:27.000000', NULL, 1),
(6956207, 1048609, 101668, '<td valign="top">One can wear and use that pair of shoes only once....Great shot</td>', 'One can wear and use that pair of shoes only once....Great shot', '2013-01-13 08:33:51.000000', NULL, 1),
(6956256, 1048628, 39880, '<td valign="top">Nice take on the challenge and, of course, good choice in cameras.  I think it''s a bit dark on the left side of the picture.  In my opinion more even light would be better.</td>', 'Nice take on the challenge and, of course, good choice in cameras.  I think it''s a bit dark on the left side of the picture.  In my opinion more even light would be better.', '2013-01-13 11:21:35.000000', NULL, 1),
(6956258, 1048125, 39880, '<td valign="top">Very cool.  I like the moody feel of this.  I could picture this as a book cover or something like that.</td>', 'Very cool.  I like the moody feel of this.  I could picture this as a book cover or something like that.', '2013-01-13 11:22:16.000000', NULL, 1),
(6956260, 1048068, 39880, '<td valign="top">Nice B&amp;W tones.  I like the detail on the wood.  I think if you cropped tighter on the texture of the wood it would make for a better shot.</td>', 'Nice B&W tones.  I like the detail on the wood.  I think if you cropped tighter on the texture of the wood it would make for a better shot.', '2013-01-13 11:23:33.000000', NULL, 1),
(6956262, 1048560, 39880, '<td valign="top">Seems a little fuzzy.  The scene doesn''t really draw me in.</td>', 'Seems a little fuzzy.  The scene doesn''t really draw me in.', '2013-01-13 11:24:45.000000', NULL, 1),
(6956263, 1048238, 39880, '<td valign="top">It looks a little soft.  I''d like to see a faster shutter speed so that we could see the coins without the blur.</td>', 'It looks a little soft.  I''d like to see a faster shutter speed so that we could see the coins without the blur.', '2013-01-13 11:25:37.000000', NULL, 1),
(6956265, 1048063, 39880, '<td valign="top">I like the concept here, but think it needs better lighting.</td>', 'I like the concept here, but think it needs better lighting.', '2013-01-13 11:26:27.000000', NULL, 1),
(6956266, 1048601, 39880, '<td valign="top">I like this idea, but I feel the long line on the right (is it a fence post?) distracts from the reflections of the branches.</td>', 'I like this idea, but I feel the long line on the right (is it a fence post?) distracts from the reflections of the branches.', '2013-01-13 11:28:08.000000', NULL, 1),
(6956268, 1048147, 39880, '<td valign="top">I like the idea here but would like to see more people on the sidewalk to add a bit more interest.</td>', 'I like the idea here but would like to see more people on the sidewalk to add a bit more interest.', '2013-01-13 11:30:05.000000', NULL, 1),
(6956269, 1047697, 39880, '<td valign="top">With the guy running out of the frame, my eyes wander out of the frame.  Having the guy in the center would help.  An actual title would help, as well.</td>', 'With the guy running out of the frame, my eyes wander out of the frame.  Having the guy in the center would help.  An actual title would help, as well.', '2013-01-13 11:32:09.000000', NULL, 1),
(6956291, 1047994, 18505, '<td valign="top">Great resolution - just don''t use Chantix...</td>', 'Great resolution - just don''t use Chantix...', '2013-01-13 12:16:30.000000', NULL, 1),
(6956292, 1048068, 18505, '<td valign="top">No vote - just a comment...  I love the use of black and white in this image - It emphasizes the wonderful textures and tones.  Good luck with the new roof!!!</td>', 'No vote - just a comment...  I love the use of black and white in this image - It emphasizes the wonderful textures and tones.  Good luck with the new roof!!!', '2013-01-13 12:18:26.000000', NULL, 1),
(6956443, 1048536, 35357, '<td valign="top">Light a candle, dude !</td>', 'Light a candle, dude !', '2013-01-13 16:14:17.000000', NULL, 1),
(6956528, 1047994, 10785, '<td valign="top">Good color and sharpness. I think the only critique would be to get closer and leave less table space in the foreground in order to get more personal with the subject.</td>', 'Good color and sharpness. I think the only critique would be to get closer and leave less table space in the foreground in order to get more personal with the subject.', '2013-01-13 19:58:58.000000', NULL, 1),
(6956671, 1048546, 124982, '<td valign="top">A little underexposed...but quite beautiful!</td>', 'A little underexposed...but quite beautiful!', '2013-01-13 22:01:04.000000', NULL, 1),
(6956672, 1048250, 124982, '<td valign="top">Excellent!! Lovely lighting and composition! Top 3 for sure!</td>', 'Excellent!! Lovely lighting and composition! Top 3 for sure!', '2013-01-13 22:01:55.000000', NULL, 1),
(6956682, 1047989, 124982, '<td valign="top">Lovely IR.</td>', 'Lovely IR.', '2013-01-13 22:05:49.000000', NULL, 1),
(6956683, 1047981, 124982, '<td valign="top">Keep shooting macros like this and you''ll be raking in the ribbons! Quite lovely! Top 3 for me!</td>', 'Keep shooting macros like this and you''ll be raking in the ribbons! Quite lovely! Top 3 for me!', '2013-01-13 22:07:42.000000', NULL, 1),
(6956733, 1047699, 15511, '<td valign="top">I''m thinking that the lights should be on. Many commercial images use that to good effect, and it would then probably keep that orange reflector from sticking out like a sore thumb. I''d likely have taken that off before shooting.</td>', 'I''m thinking that the lights should be on. Many commercial images use that to good effect, and it would then probably keep that orange reflector from sticking out like a sore thumb. I''d likely have taken that off before shooting.', '2013-01-13 23:21:21.000000', NULL, 1),
