(6958219, 1048488, 11769, '<td valign="top">Love the light</td>', 'Love the light', '2013-01-15 19:06:18.000000', NULL, 1),
(6958220, 1048614, 11769, '<td valign="top">And that is a good start. Next exhale. Wonderful controlled blur.</td>', 'And that is a good start. Next exhale. Wonderful controlled blur.', '2013-01-15 19:08:22.000000', NULL, 1),
(6958221, 1048601, 11769, '<td valign="top">Lovely</td>', 'Lovely', '2013-01-15 19:09:00.000000', NULL, 1),
